/* Month-only payment calendar, derived from active subscription schedules. */
(()=>{'use strict';
const KEY='substop.subscriptions.v1';const list=document.getElementById('payments-list');const title=document.querySelector('#calendar .section-head h2');const today=new Date();let month=new Date(today.getFullYear(),today.getMonth(),1,12);
title.textContent='Płatności w miesiącu';const toolbar=document.createElement('div');toolbar.className='calendar-toolbar';toolbar.innerHTML='<button type="button" id="month-prev" aria-label="Poprzedni miesiąc">‹</button><strong id="month-current"></strong><button type="button" id="month-next" aria-label="Następny miesiąc">›</button>';title.parentElement.after(toolbar);const summary=document.createElement('div');summary.className='calendar-summary';summary.innerHTML='<span>Łącznie do zapłaty</span><b id="month-total">0,00 zł</b>';toolbar.after(summary);
const formatMoney=n=>new Intl.NumberFormat('pl-PL',{style:'currency',currency:'PLN'}).format(n);const localDate=s=>{const [y,m,d]=s.split('-').map(Number);return new Date(y,m-1,d,12)};const dKey=d=>d.getFullYear()*12+d.getMonth();const monthStep=(base,n)=>{const target=new Date(base.getFullYear(),base.getMonth()+n,1,12);const max=new Date(target.getFullYear(),target.getMonth()+1,0).getDate();target.setDate(Math.min(base.getDate(),max));return target};
function entriesFor(s,start,end){const base=localDate(s.date);if(Number.isNaN(base.getTime())||base>end)return[];const found=[];
if(s.cycle==='weekly'){let step=Math.max(0,Math.ceil((start-base)/86400000/7));let at=new Date(base.getFullYear(),base.getMonth(),base.getDate()+step*7,12);while(at<=end&&found.length<6){if(at>=start)found.push(at);step++;at=new Date(base.getFullYear(),base.getMonth(),base.getDate()+step*7,12)}}
else{const stride=s.cycle==='yearly'?12:1;let n=Math.max(0,Math.floor((dKey(start)-dKey(base))/stride)-1);let at=monthStep(base,n*stride);while(at<=end){if(at>=start)found.push(at);n++;at=monthStep(base,n*stride);if(n>10000)break}}return found}
function read(){try{const data=JSON.parse(localStorage.getItem(KEY)||'[]');return Array.isArray(data)?data:[]}catch{return []}}
const observer=new MutationObserver(()=>render());function render(){observer.disconnect();const start=new Date(month.getFullYear(),month.getMonth(),1,12),end=new Date(month.getFullYear(),month.getMonth()+1,0,12);const payments=[];for(const s of read().filter(x=>x.status==='active'))for(const at of entriesFor(s,start,end))payments.push({at,name:s.name,amount:s.amount});payments.sort((a,b)=>a.at-b.at||a.name.localeCompare(b.name,'pl'));document.getElementById('month-current').textContent=new Intl.DateTimeFormat('pl-PL',{month:'long',year:'numeric'}).format(month);document.getElementById('month-total').textContent=formatMoney(payments.reduce((t,x)=>t+x.amount,0));list.replaceChildren();if(!payments.length){const empty=document.createElement('div');empty.className='cancel-empty';empty.textContent='Brak zaplanowanych płatności w tym miesiącu.';list.append(empty)}else for(const p of payments){const row=document.createElement('div');row.className='month-row';const left=document.createElement('div');const name=document.createElement('b');name.textContent=p.name;const date=document.createElement('div');date.className='hint';date.textContent=new Intl.DateTimeFormat('pl-PL',{day:'numeric',month:'long'}).format(p.at);left.append(name,date);const price=document.createElement('b');price.textContent=formatMoney(p.amount);row.append(left,price);list.append(row)}observer.observe(list,{childList:true})}
document.getElementById('month-prev').addEventListener('click',()=>{month=new Date(month.getFullYear(),month.getMonth()-1,1,12);render()});document.getElementById('month-next').addEventListener('click',()=>{month=new Date(month.getFullYear(),month.getMonth()+1,1,12);render()});render();
window.addEventListener('substop:changed',render);window.addEventListener('substop:navigate',render);
})();
